{
  "done": false,
  "tool": "manage_backends",
  "args": {
    "operation": "add",
    "apps_json": [
      {
        "name": "Surveillance Settings Room",
        "description": "Alerts, notes, and policy settings.",
        "tabs": {
          "alerts": {
            "id": "alerts",
            "name": "Alerts",
            "layout": [
              {
                "i": "alert_metric",
                "x": 0,
                "y": 0,
                "w": 6,
                "h": 4
              },
              {
                "i": "case_notes",
                "x": 6,
                "y": 0,
                "w": 12,
                "h": 8
              }
            ]
          },
          "policy": {
            "id": "policy",
            "name": "Policy",
            "layout": [
              {
                "i": "policy_pdf",
                "x": 0,
                "y": 0,
                "w": 16,
                "h": 14
              }
            ]
          }
        }
      }
    ],
    "widgets_json": {
      "alert_metric": {
        "name": "Open Alerts",
        "description": "Open alert count.",
        "endpoint": "/alert-count",
        "type": "metric",
        "params": [],
        "data": {
          "w": 5,
          "h": 4
        },
        "category": "Surveillance",
        "staleTime": 1800000
      },
      "case_notes": {
        "name": "Case Notes",
        "description": "Notes for one surveillance case.",
        "endpoint": "/case-notes",
        "type": "markdown",
        "params": [
          {
            "paramName": "case_id",
            "type": "text",
            "label": "Case",
            "value": "C-1042",
            "description": "Case identifier."
          }
        ],
        "data": {
          "w": 12,
          "h": 8
        },
        "category": "Surveillance",
        "staleTime": 1800000
      },
      "policy_pdf": {
        "name": "Policy Digest",
        "description": "Latest surveillance policy digest.",
        "endpoint": "/policy-digest",
        "type": "pdf",
        "params": [],
        "data": {
          "w": 16,
          "h": 14
        },
        "category": "Surveillance",
        "staleTime": 1800000
      }
    }
  }
}

